function drawCat() {
	push()
	const w = width
	const h = height
	const s = min(w, h * 0.5);
	fill(0)
	noStroke()

	circle(w * 0.5, h * 0.5, s)
	triangle(w * 0.35, h * 0.2,
					 w * 0.3, h * 0.4,
					 w * 0.4, h * 0.4
					)
	triangle(w * 0.65, h * 0.2,
					 w * 0.6, h * 0.4,
					 w * 0.7, h * 0.4
					)	
	erase();
	circle(w * 0.4, h * 0.45, s * 0.2)
	circle(w * 0.6, h * 0.45, s * 0.2)
	circle(w * 0.5, h * 0.55, s * 0.15)
	arc(w * 0.5, h * 0.55, s * 0.6, s * 0.5, 0, PI)
	noErase();
	arc(w * 0.5, h * 0.55, s * 0.6, s * 0.15, 0, PI)
	erase();
	ellipse(w * 0.5, h * 0.55, s * 0.15, s * 0.035)
	noErase();
	pop()
	if (noise(frameCount * 0.01) < 0.35) erase() // ^^
}

class Flower {
	constructor(num, dst, sze)  {
		this.pos = createVector(random(width * -0.3, width * 1.3), random(height * -0.3, height * 1.3))
		this.seed = random(34875629);
		this.num = num;
		this.dst = dst;
		this.sze = sze;
		this.ang = random(TWO_PI);
		this.clrs = ["red", "green", "blue"];
		this.clrs = ["purple", "white"];
	}
	update()  {
		// this.ang += 0.01
	}
	show()  {
		push();
		blendMode(DIFFERENCE);
		noiseSeed(this.seed);
		const xo = 0; // (noise(123 + frameCount * 0.008512) - 0.5) * this.dst
		const yo = 0; // (noise(234 + frameCount * 0.008134) - 0.5) * this.dst
		translate(this.pos.x + xo, this.pos.y + yo)
		rotate(frameCount * 0.01)
		noStroke();
		for (let i = 0; i < this.num; i++) {
			const ang = this.ang + i / this.num * TWO_PI;
			var dst = sin(this.ang + frameCount * 0.01) * this.dst
			const x = cos(ang) * dst;
			const y = sin(ang) * dst;
			fill(this.clrs[i % this.clrs.length]);
			circle(x, y, this.sze);
		}
		pop();
	}
}
